// One renderer and one encounter field keep Trauma and Cardiac arrest in sync.
export function traumaArrestPanel(fields,icon,source){return `<details class="trauma-arrest-panel" ${fields['trauma-arrest-open']?'open':''}><summary><span class="trauma-arrest-icon">${icon('heart')}</span><span><b>Trauma arrest</b><small>Before arrival / en route · Bleeding, chest, oxygenation, volume</small></span><span class="trauma-arrest-expand" aria-hidden="true">+</span></summary><div class="trauma-arrest-content">
  <div class="trauma-arrest-heading"><span>QUICK BRIEF · ADULT & PEDIATRIC</span>${source('TRAUMATIC ARREST · S509',148)}</div>
  <section class="trauma-arrest-prep"><h3>Before arrival: assign roles, bring the fixes</h3><p><b>Turn main O2 on.</b> Ready suction / BVM, hemorrhage kit, bilateral decompression equipment, IV / IO + saline / pressure bag, and monitor / pads. Assign bleeding, chest / airway, and access roles in parallel. Plan the destination and early hospital notification.</p></section>
  <div class="trauma-arrest-focus"><strong>Fix blood loss, trapped chest pressure, and oxygenation.</strong><p>Start CPR and monitoring alongside cause-directed treatment. If trauma does not explain the arrest, use the medical-arrest pathway (SB204).</p></div>
  <div class="trauma-arrest-actions">
    <section data-trauma-priority="bleeding"><span>01</span><div><h3>Stop external bleeding</h3><p>Use direct pressure, wound packing / dressings, and tourniquets as indicated. During transport, confirm hemorrhage control is still effective.</p>${source('HEMORRHAGE · T710',199)}</div></section>
    <section data-trauma-priority="chest"><span>02</span><div><h3>Decompress both sides · ALS</h3><p>For blunt trauma or penetrating torso injury, S509 calls for bilateral needle decompression per T701. With persistent arrest, reassess for ineffective decompression / recurrent tension; repeat when indicated by S509.</p></div></section>
    <section data-trauma-priority="oxygen"><span>03</span><div><h3>Get oxygen in; secure the airway</h3><p>Use BVM or an advanced airway as indicated. En route, reassess ventilation, airway security, and waveform ETCO₂.</p>${source('AIRWAY · T705',189)}</div></section>
    <section data-trauma-priority="volume"><span>04</span><div><h3>Access + fluid actually flowing</h3><p>Establish IV / IO. S509: adult NS 1 L; pediatric NS 20 mL/kg. Use open flow / a pressure bag for IO as specified. Recheck the line and delivery.</p></div></section>
  </div>
  <section class="trauma-arrest-transport"><h3>Rhythm, destination & medical control</h3><div class="trauma-arrest-rhythms"><p><b>VF / pulseless VT:</b> shock per C300 / P601, fluids, consider repeat decompression, nearest trauma center.</p><p><b>PEA &gt;40 bpm:</b> fluids, consider repeat decompression, nearest trauma center.</p><p><b>Asystole / PEA &lt;40 bpm:</b> contact Medical Control about termination. Do not make a termination decision from this brief.</p></div><p><b>Expedite:</b> EMS-witnessed penetrating arrest → nearest trauma center; ROSC → immediate transport. Under 18: pediatric trauma center may be used.</p><p><b>Pregnancy exception:</b> known pregnancy &gt;24 weeks or fundus at / above the umbilicus → nearest ED for possible resuscitative delivery.</p></section>
  <aside class="trauma-arrest-exclusions"><b>Traumatic / hypovolemic arrest: S509 does not recommend routine epi / atropine. TXA is not beneficial in traumatic arrest. Do not initiate post-ROSC cooling.</b></aside>
  <div class="trauma-arrest-links">${source('S509 · FULL PROTOCOL & TRANSPORT',148)}${source('S509 · NOTES & TERMINATION',149)}</div>
</div></details>`;}
export function rememberTraumaArrest(fields){const panel=document.querySelector('.trauma-arrest-panel');if(panel)fields['trauma-arrest-open']=panel.open;}
export function bindTraumaArrest(getState,save){document.addEventListener('toggle',e=>{if(e.target.matches('.trauma-arrest-panel')){getState().fields['trauma-arrest-open']=e.target.open;save();}},true);}
